  }>,
  env: Env,
  batchId: string,
): Promise<Map<string, string | null>> {
  const transcripts = new Map<string, string | null>()

  // Always fetch transcripts from GitHub and re-store them.
  // This ensures reindexing actually refreshes stale data (e.g. after transcript
  // scoping changes) rather than serving cached unscoped transcripts from the DB.
  if (checkpoints.length > 0 && installationId) {
    try {
      // Resolve the numeric GitHub installation ID from our internal FK
      const githubInstallationId = await db.installations.getGithubId(installationId)
      if (!githubInstallationId) {
        log("transcript_no_github_installation", { batchId, repoId, installationId })
        return transcripts
      }

      const token = await getInstallationToken(
        githubInstallationId,
        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
        env.ENTIRE_CACHE,
      )

      const dbUpdates: Array<{ checkpoint_id: string; transcript_stripped: string }> = []

      // Fetch in parallel with concurrency limit
      for (let i = 0; i < checkpoints.length; i += TRANSCRIPT_CONCURRENCY) {
        const transcriptBatch = checkpoints.slice(i, i + TRANSCRIPT_CONCURRENCY)
        const results = await Promise.all(
          transcriptBatch.map((cp) =>
            fetchAndStripTranscript(
              repoFullName,
              cp.checkpoint_id,
              cp.session_count,
              cp.agent,
              (cp.sessions as SessionInfo[] | null) ?? null,
              token,
            ),
          ),
        )

        for (let j = 0; j < results.length; j++) {
          const cp = transcriptBatch[j]
          const sessions = results[j]
          if (sessions) {
            dbUpdates.push({
              checkpoint_id: cp.checkpoint_id,
              transcript_stripped: JSON.stringify(sessions),
            })

            // Store session 0 JSONL for chunk-building in the caller
            const primaryJsonl = sessions["0"]
            transcripts.set(cp.checkpoint_id, primaryJsonl ?? null)
          }
        }
      }

      // Store stripped transcripts in DB
      if (dbUpdates.length > 0) {
        const stored = await db.checkpoints.updateTranscriptBatch(repoId, dbUpdates)
        if (stored > 0) {
          await invalidateTranscriptCacheEntries(
            env.ENTIRE_CACHE,
            repoFullName,
            dbUpdates.map((update) => update.checkpoint_id),
          )
        }
        log("transcripts_stored", { batchId, repoId, stored, attempted: dbUpdates.length })
      }
