// --- Transcript Functions ---

// Kysely auto-parses JSON columns on read, so we re-stringify them here to return
// plain strings that callers can JSON.parse(). The updateTranscriptBatch() below
// writes raw JSON strings, and Kysely's JSON column type handles the MySQL <-> JS
// conversion transparently in both directions.
export async function getCheckpointTranscript(
  db: Kysely<DB>,
  repoId: string,
  checkpointId: string,
): Promise<{ transcript_stripped: string | null; sessions: string | null } | null> {
  // Two separate queries: transcript from new table, sessions from checkpoints
  const [transcriptRow, checkpointRow] = await Promise.all([
    db
      .selectFrom("repo_checkpoint_transcripts")
      .select("transcript_stripped")
      .where("repo_id", "=", repoId)
      .where("checkpoint_id", "=", checkpointId)
      .executeTakeFirst(),
    db
      .selectFrom("repo_checkpoints")
      .select("sessions")
      .where("repo_id", "=", repoId)
      .where("checkpoint_id", "=", checkpointId)
      .executeTakeFirst(),
  ])

  if (!transcriptRow && !checkpointRow) return null

  return {
    transcript_stripped: transcriptRow?.transcript_stripped
      ? JSON.stringify(transcriptRow.transcript_stripped)
      : null,
    sessions: checkpointRow?.sessions ? JSON.stringify(checkpointRow.sessions) : null,
  }
}

export async function getCheckpointTranscriptBatch(
  db: Kysely<DB>,
  repoId: string,
  checkpointIds: string[],
): Promise<Array<{ checkpoint_id: string; transcript_stripped: string | null }>> {
  if (checkpointIds.length === 0) return []

  const rows = await db
    .selectFrom("repo_checkpoint_transcripts")
    .select(["checkpoint_id", "transcript_stripped"])
    .where("repo_id", "=", repoId)
    .where("checkpoint_id", "in", checkpointIds)
    .execute()

  return rows.map((row) => ({
    checkpoint_id: row.checkpoint_id,
    transcript_stripped: row.transcript_stripped ? JSON.stringify(row.transcript_stripped) : null,
  }))
}

export async function updateTranscriptBatch(
  db: Kysely<DB>,
  repoId: string,
  updates: Array<{ checkpoint_id: string; transcript_stripped: string }>,
): Promise<number> {
  if (updates.length === 0) return 0

  let upserted = 0
  for (let i = 0; i < updates.length; i += BATCH_SIZE) {
    const batch = updates.slice(i, i + BATCH_SIZE)
    for (const { checkpoint_id, transcript_stripped } of batch) {
      try {
        await db
          .insertInto("repo_checkpoint_transcripts")
          .values({
            id: generateId(),
            repo_id: repoId,
            checkpoint_id,
            transcript_stripped: transcript_stripped as unknown as string,
          })
          .onDuplicateKeyUpdate({
            transcript_stripped: transcript_stripped as unknown as string,
          })
          .execute()
        upserted++
      } catch (e) {
        console.log(
          `${LOG_PREFIX} update_transcript_error`,
          JSON.stringify({
            checkpoint_id,
            error: String(e),
          }),
        )
      }
    }
  }
  return upserted
}

