export async function generateAndStoreReview(
  env: Env,
  db: Db,
  repoFullName: string,
  repoGithubId: number,
  repoInstallationId: string | null,
  repoId: string,
  checkpointId: string,
  queuedAt: string,
): Promise<CheckpointAnalysis> {
  if (!env.ANTHROPIC_API_KEY) {
    throw new Error("ANTHROPIC_API_KEY is not configured")
  }

  let token: string | undefined
  if (repoInstallationId) {
    const githubInstallationId = await db.installations.getGithubId(repoInstallationId)
    if (githubInstallationId) {
      token = await getInstallationToken(
        githubInstallationId,
        { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
        env.ENTIRE_CACHE,
      )
    }
  }

  const checkpointLocation = await db.checkpoints.findById(repoId, checkpointId)
  if (!checkpointLocation?.commit) {
    await db.analyses.markFailed(repoId, checkpointId, "Checkpoint not found in database", queuedAt)
    throw new Error("Checkpoint not found in database")
  }

  const transcriptRow = await db.checkpoints.getTranscript(repoId, checkpointId)
  const transcriptStripped = transcriptRow?.transcript_stripped ?? null

  // Parse stripped transcript once and reuse for sessions, tool usage, and tool profile
  let parsedSessionsMap: Record<string, string> | null = null
  if (transcriptStripped) {
    try {
      parsedSessionsMap = JSON.parse(transcriptStripped) as Record<string, string>
    } catch {
      // Ignore malformed stripped transcript payloads.
    }
  }

  let sessions: SessionTranscript[]
  if (parsedSessionsMap) {
    const sessionMetadata = await fetchSessionMetadataBatch(
      repoFullName,
      checkpointId,
      checkpointLocation.commit.session_count ?? 1,
      token,
    )
    sessions = buildSessionsFromStrippedTranscript(parsedSessionsMap, sessionMetadata)

    if (sessions.length === 0) {
      log("stripped_transcript_empty_fallback", { repoId, checkpointId })
      sessions = await fetchTranscriptSessions(repoFullName, checkpointId, token)
    } else {
      log("sessions_from_db", { repoId, checkpointId, sessionCount: sessions.length })
    }
  } else {
    log("no_stripped_transcript_fallback", { repoId, checkpointId })
    sessions = await fetchTranscriptSessions(repoFullName, checkpointId, token)
  }

  if (sessions.length === 0) {
    await db.analyses.markFailed(repoId, checkpointId, "No transcript data available", queuedAt)
    throw new Error("No transcript data available")
  }

  const toolUsage = parsedSessionsMap
    ? extractToolUsageFromSessionsMap(parsedSessionsMap)
    : { skillsUsed: [], mcpServersUsed: [], modelsUsed: [] }
  const toolProfile =
    (parsedSessionsMap ? extractToolProfile(parsedSessionsMap) : null) ?? undefined

  const review = await generateCheckpointAnalysis(
    env.ANTHROPIC_API_KEY,
    sessions,
    checkpointLocation.commit,
    checkpointId,
  )

  const agentsUsed = [...new Set(sessions.map((session) => session.agent))]
  const fullReview: CheckpointAnalysis = { ...review, ...toolUsage, agentsUsed, toolProfile }

  await db.analyses.markComplete(repoId, checkpointId, JSON.stringify(fullReview), queuedAt)
  await reindexWithAnalysis(env, repoGithubId, checkpointLocation.commit, fullReview)

  return fullReview
}

