}

// Convert checkpoint_id (12 hex chars = 48 bits) to a numeric ID for Turbopuffer.
// 48 bits fits within Number.MAX_SAFE_INTEGER (53 bits), so no hashing needed.
// Uses Number("0x" + id) instead of parseInt because parseInt processes the value
// as a 32-bit signed integer internally, producing wrong results for IDs >= 2^31.
export function checkpointIdToNumeric(checkpointId: string): number {
  const id = Number("0x" + checkpointId)
  if (Number.isNaN(id)) {
    throw new Error(`Invalid hex checkpoint_id: ${checkpointId}`)
  }
  return id
}

