// SearchService: orchestrates hybrid search across repos and checkpoints.
// Always runs both semantic (Turbopuffer) and keyword (DB LIKE) search in
// parallel, then merges results. Cohere reranking is applied when available.

import type { PostHog } from "posthog-node"

import { getAccessibleReposByUser, searchReposByUser } from "./planetscale/repos"
import { searchCheckpointsKeyword, getCheckpointsByIdsGlobal } from "./planetscale/search-queries"
import { isFeatureEnabled } from "./posthog"
import { rerankWithSummaries } from "./search-reranker"
import type {
  SearchMatchType,
  SearchResult,
  SearchResponse,
  SearchParams,
  CheckpointResult,
} from "./search-types"
import type { ChunkRRFResult } from "./turbopuffer"
import { embedQueryVector, searchChunksOrg } from "./turbopuffer"

export type { SearchResult, SearchResponse, SearchParams }

// Max chunk hits to keep in memory across all org namespaces before dedup/sort.
const MAX_CHUNK_HEAP = 1000

// Max concurrent org namespace queries (each fires 2 Turbopuffer requests)
const ORG_QUERY_CONCURRENCY = 5

// Domain-specific stop words stripped from BM25 queries only.
const DOMAIN_STOP_WORDS = new Set(["checkpoint", "checkpoints"])

function stripDomainStopWords(query: string): string {
  const words = query.split(/\s+/).filter((w) => !DOMAIN_STOP_WORDS.has(w.toLowerCase()))
  return words.join(" ") || query
}

// ─── SearchService ────────────────────────────────────────────────────────────

export class SearchService {
  constructor(
    private readonly db: any,
    private readonly turbopufferApiKey: string | undefined,
    private readonly openaiApiKey: string | undefined,
    private readonly semanticSearchEnabled: boolean,
    private readonly cache?: KVNamespace,
    private readonly posthog?: PostHog | null,
    private readonly cohereApiKey?: string,
  ) {}

  async search(userId: string, params: SearchParams): Promise<SearchResponse> {
    const totalStart = Date.now()
    const { types = ["repos", "checkpoints"] } = params
    const allResults: SearchResult[] = []

    let keyword_ms: number | null = null
    let embedding_ms: number | null = null
    let vector_ms: number | null = null
    let rerank_ms: number | null = null
    let reranked: boolean | undefined

    if (types.includes("repos")) {
      const repos = await this.searchRepos(userId, params)
      allResults.push(...repos)
    }

    if (types.includes("checkpoints")) {
      // Always run both keyword and semantic search in parallel, then merge.
      const kwPromise = (async () => {
        const kwStart = Date.now()
        const results = await this.searchCheckpointsKeyword(userId, params)
        keyword_ms = Date.now() - kwStart
        return results
      })()
      const semanticPromise = this.semanticSearchEnabled
        ? (async () => {
            const embedStart = Date.now()
            const queryVector = await embedQueryVector(this.openaiApiKey!, params.q)
            embedding_ms = Date.now() - embedStart

            const vectorStart = Date.now()
            const results = await this.searchCheckpointsSemantic(userId, params, queryVector)
            vector_ms = Date.now() - vectorStart
            return results
          })()
        : Promise.resolve([] as SearchResult[])

      const [kwResults, semanticResults] = await Promise.all([kwPromise, semanticPromise])

      // Merge: semantic results take priority, keyword fills gaps
      const seenIds = new Set(
        semanticResults.map((r) => (r.type === "checkpoint" ? r.data.id : "")),
      )
      allResults.push(...semanticResults)
      for (const r of kwResults) {
        if (r.type === "checkpoint" && !seenIds.has(r.data.id)) {
          allResults.push(r)
        }
      }
    }

    // Sort by score descending
    allResults.sort((a, b) => b.searchMeta.score - a.searchMeta.score)

    if (this.cohereApiKey && allResults.some((r) => r.type === "checkpoint")) {
      const rerankStart = Date.now()
      const rerankOutput = await rerankWithSummaries(
        this.cohereApiKey,
        params.q,
        allResults,
        this.cache,
      )
      rerank_ms = Date.now() - rerankStart
      reranked = rerankOutput.reranked
      allResults.splice(0, allResults.length, ...rerankOutput.results)
    }

    const total = allResults.length
    const safePage = Math.max(1, params.page)
    const start = (safePage - 1) * params.limit
    const results = allResults.slice(start, start + params.limit)

